-- Test data for the activity code cross-reference tables, copied from the RESULTS (Oracle) tables
-- THE.SILV_ACTIVITY_XREF, THE.SILV_BASE_OBJECTIVE_XREF and THE.SILV_BASE_FUNDING_XREF.
-- Runs after V999.0.1, which loads the code tables these rows reference.

-- Every base has the same objectives (152 values), and the same funding sources (76 values) except DN, which has no FIP.
INSERT INTO silva.silv_base_objective_xref (silv_base_code, silv_objective_code)
SELECT b.code, o.code
FROM unnest(string_to_array('AU,BR,CC,CM,DN,DS,EP,FE,HC,HI,JS,LB,PC,PL,PR,RC,RD,SP,ST,SU,SX', ',')) AS b(code)
CROSS JOIN unnest(string_to_array('2BT,A,AC,AHM,ALP,AMD,AMP,ARC,BIO,BR,BTR,CBU,CC,CE,CGE,COM,CON,CR,CSB,CT,CUB,D,DA,DAF,DD,DG,DL,DM,DR,DS,DSA,DTA,ECO,EFF,ER,ERO,EST,FE,FG,FH,FIS,FM,FN,FP,FRA,FRE,FUR,FWD,FWF,GB,GOS,GRA,HAZ,HER,HPR,HSR,I,IA,IB,ID,INC,INN,INS,IS,IVT,IW,JS,LPR,LPS,MAP,MAX,MG,MIG,MLS,MMU,MNT,MON,MOO,MS,MTC,MTS,N,NAT,ND,NG,NOA,NUT,OGF,ONC,PER,PH,PL,PLT,POL,PP,PR,PRP,PRY,PVM,RA,RCR,RE,REC,REM,REP,RG,RH,RHM,RIP,RP,RS,RT,SAL,SAN,SBI,SC,SE,SEE,SEM,SH,SM,SMP,SNP,SP,SPE,SPR,SR,SRI,ST,STC,STD,STE,STU,SU,SUP,SVF,SVO,SVW,SWF,TEM,TP,TWD,UNG,UPG,UR,VM,W,WET,WHM,WND,WQI,WT', ',')) AS o(code)
ON CONFLICT DO NOTHING;

INSERT INTO silva.silv_base_funding_xref (silv_fund_srce_code, silv_base_code)
SELECT f.code, b.code
FROM unnest(string_to_array('AU,BR,CC,CM,DN,DS,EP,FE,HC,HI,JS,LB,PC,PL,PR,RC,RD,SP,ST,SU,SX', ',')) AS b(code)
CROSS JOIN unnest(string_to_array('BCP,BCT,CBI,CF,CFR,CL,ERP,FCE,FCM,FED,FEP,FES,FID,FIL,FIM,FIP,FIV,FMC,FME,FMY,FR,FRP,FTL,FTM,GA,GAC,GEN,GFS,GJF,GJJ,GJM,HBF,HCA,HCB,HCR,HDU,HFB,HFE,HFF,HFW,HHC,HLB,HNC,HNF,HNT,HSR,HTW,IA,IIR,IIV,IO,IR,JOP,LFP,LPP,M,O,RBC,RBL,RBM,S,SBF,SMF,TEB,TSC,TTO,VCV,VFH,VFP,VG,VI,VOB,VOI,VRT,WRR,XXX', ',')) AS f(code)
WHERE NOT (b.code = 'DN' AND f.code = 'FIP')
ON CONFLICT DO NOTHING;

